// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.explanation.StrategyDecision;

/**
 * Everything the selector concluded about one dispatch: every strategy that was asked, whether it was admitted, its
 * priced interval, what eliminated it, and the single reason the winner won. Explanations, logs and telemetry render
 * this record; they never recompute the decision.
 *
 * @param point   the decision point
 * @param mode    {@code normal}, {@code forced} or {@code direct}
 * @param entries one per strategy asked (declined) or per admitted candidate, in registry order
 * @param winner  index into {@code entries} of the selected candidate, or -1
 * @param reason  why the winner won, or why nothing was selected
 */
record LmdbNativeDecisionRecord(LmdbNativeDecisionPoint point, String mode, List<Entry> entries, int winner,
		String reason) {

	/**
	 * One strategy or candidate in the decision.
	 *
	 * @param id            strategy tag
	 * @param admitted      whether the strategy produced a candidate
	 * @param declineReason the strategy's own reason when not admitted
	 * @param nanos         the priced interval of the candidate, or null when declined
	 * @param expectedNanos the expected price, or NaN
	 * @param eliminatedBy  what removed the candidate from the frontier, or null when it stayed eligible
	 * @param features      the priced feature vector (after slice proration), or null when declined
	 */
	record Entry(String id, boolean admitted, String declineReason, LmdbNativeWork nanos, double expectedNanos,
			String eliminatedBy, LmdbNativeCostVector features) {

		static Entry declined(String id, String reason) {
			return new Entry(id, false, reason, null, Double.NaN, null, null);
		}
	}

	LmdbNativeDecisionRecord {
		entries = List.copyOf(entries);
	}

	String winnerId() {
		return winner < 0 ? null : entries.get(winner).id();
	}

	/** Every entry on one line each: the trace form written when {@code rdf4j.lmdb.nativeDecisions.trace} is set. */
	String describe(String label) {
		StringBuilder out = new StringBuilder("native decision ").append(label)
				.append(" [")
				.append(mode)
				.append("] winner=")
				.append(winnerId())
				.append(" reason=")
				.append(reason);
		for (int i = 0; i < entries.size(); i++) {
			Entry entry = entries.get(i);
			out.append("\n  ").append(i == winner ? "* " : "  ").append(entry.id());
			if (!entry.admitted()) {
				out.append(" declined: ").append(entry.declineReason());
			} else {
				out.append(' ').append(render(entry));
				if (entry.eliminatedBy() != null) {
					out.append(" eliminated: ").append(entry.eliminatedBy());
				}
			}
		}
		return out.toString();
	}

	/** The public explain record: the winner first, then the eligible and eliminated candidates, then the declined. */
	StrategyDecision toStrategyDecision(String decisionPointLabel) {
		List<StrategyDecision.Candidate> candidates = new ArrayList<>(entries.size());
		int priority = 1;
		if (winner >= 0) {
			candidates.add(new StrategyDecision.Candidate(entries.get(winner).id(), priority++, true,
					"Would select now", null, "Execution-time binding and admission must still succeed"));
		}
		for (int i = 0; i < entries.size(); i++) {
			Entry entry = entries.get(i);
			if (i == winner || !entry.admitted()) {
				continue;
			}
			boolean eliminated = entry.eliminatedBy() != null;
			candidates.add(new StrategyDecision.Candidate(entry.id(), priority++, true,
					eliminated ? "Eliminated" : "Eligible",
					null, eliminated ? entry.eliminatedBy() : "Priced " + render(entry)));
		}
		for (Entry entry : entries) {
			if (!entry.admitted()) {
				candidates.add(new StrategyDecision.Candidate(entry.id(), null, false, "Declined",
						entry.declineReason(), null));
			}
		}
		return new StrategyDecision(decisionPointLabel, System.currentTimeMillis(), mode, winnerId(), null, reason,
				candidates);
	}

	private static String render(Entry entry) {
		if (entry.nanos() == null) {
			return "unpriced";
		}
		return String.format("%.0f..%s ns (expected %.0f)", entry.nanos().low(),
				entry.nanos().known() ? String.format("%.0f", entry.nanos().high()) : "unbounded",
				entry.expectedNanos());
	}
}
